"""Build an offline review surface using computed research results only."""
from pathlib import Path
import json
import pandas as pd
P=Path(__file__).resolve().parent;R=P/'research_results'
def build():
    metrics=json.loads((R/'weather_metrics.json').read_text());rows=pd.read_csv(R/'dashboard_rows.csv')
    data={'rows':json.loads(rows.to_json(orient='records')),'metrics':metrics}
    (P/'SmogWindow_Weather_dashboard.html').write_text(TEMPLATE.replace('/*PAYLOAD*/','const D='+json.dumps(data,separators=(',',':'))+';'),encoding='utf-8')
TEMPLATE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmogWindow | Weather and probability audit</title>
<style>
:root{color-scheme:light dark;--bg:light-dark(#f6f8fb,#0b1220);--fg:light-dark(#172554,#e2e8f0);--muted:light-dark(#475569,#a8b7ca);--panel:light-dark(#fff,#142033);--line:light-dark(#cbd5e1,#334155);--accent:light-dark(#0f766e,#5eead4)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.5 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:28px 20px}h1{font-size:34px;line-height:1.2;margin:8px 0}h2{font-size:20px}p{max-width:90ch}small,.muted{color:var(--muted)}.label{color:var(--accent);letter-spacing:.1em;font-size:12px;font-weight:700}.banner{border-left:4px solid var(--accent);padding:12px 16px;background:var(--panel);margin:20px 0}.controls{display:flex;flex-wrap:wrap;gap:18px;align-items:end}label{display:block;font-size:14px}select,button{font:inherit;padding:10px;border:1px solid var(--line);border-radius:7px;background:var(--panel);color:var(--fg)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:20px 0}.metric{background:var(--panel);padding:20px;border-radius:10px}.value{font-size:32px;font-weight:650}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:right;padding:10px;border-bottom:1px solid var(--line)}th:first-child,td:first-child{text-align:left}a{color:var(--accent)}.buttonrow{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}.result{padding:16px;background:var(--panel);border-radius:8px}img{display:block;max-width:100%;height:auto}button{cursor:pointer}footer{margin-top:30px;color:var(--muted);font-size:13px}@media(max-width:700px){.grid{grid-template-columns:1fr}h1{font-size:28px}.controls>div{width:100%}select{width:100%}}
</style></head><body><main>
<div class="label">SMOGWINDOW / RESEARCH UPDATE</div><h1>Plan tomorrow. Understand the uncertainty.</h1><p class="muted">Lahore historical replay · monthly model refits · transparent comparisons</p>
<div class="banner"><b>Post-deadline research. Every displayed period is an already-inspected benchmark.</b><br>Pollution values are CAMS estimates, not ground measurements. The weather export has no forecast lead times; only weather from the UTC day before the origin is used. No live forecast or safety clearance is provided.</div>
<h2>Replay a planning decision</h2><p>Choose a historical day, inspect the forecast, then reveal the next-day reference. This prototype helps explore contingency planning; it does not authorize outdoor activity.</p><div class="controls"><div><label for="day">Forecast origin date</label><select id="day"></select></div><div><label for="threshold">Illustrative PM2.5 threshold (µg/m³)</label><select id="threshold"><option>35</option><option selected>55</option><option>100</option></select></div><div><label for="cost">Assumed missed-event : false-alarm cost</label><select id="cost"><option>1</option><option selected>3</option><option>5</option></select></div></div>
<div class="grid"><div class="metric"><span class="muted">Conditional median</span><div id="median" class="value"></div><small>µg/m³ · q50 of predictive distribution</small></div><div class="metric"><span class="muted">Central 80% interval</span><div id="interval" class="value"></div><small>q10–q90 · not guaranteed coverage</small></div><div class="metric"><span class="muted">Estimated chance above threshold</span><div id="probability" class="value"></div><small>Chance for the modeled series, not chance of safety</small></div></div>
<div class="banner"><label for="bounds">Interval method</label><select id="bounds"><option value="original">Original predictive quantiles</option><option value="adaptive">Past-only rolling adjustment</option></select><p id="boundsnote"></p></div><h2>Recent context</h2><svg id="history" viewBox="0 0 960 220" role="img" aria-label="Last 30 available daily CAMS values and next-day prediction" style="width:100%;background:var(--panel);border-radius:10px"></svg><p class="muted">Teal: available CAMS history. Orange dot: next-day median. Orange vertical line: selected interval. These are modeled values.</p><div id="decision" class="result" aria-live="polite"></div><div class="buttonrow"><button id="reveal">Reveal next-day CAMS reference</button><button id="export">Download research summary</button></div><p id="actual" class="muted"></p>
<h2>Weather is an experiment—not an assumed improvement</h2><div id="inputs" class="muted"></div><div class="table-wrap"><table><thead><tr><th>Point-forecast comparison</th><th>µg/m³</th></tr></thead><tbody id="points"></tbody></table></div><p class="muted">The probability model was selected on development CRPS and uses pollution history, because adding weather did not win that selection. Its median and the separately fitted ridge point predictions are different outputs.</p>
<h2>Does the planning flag help?</h2><p id="warningaudit"></p><p class="muted">Calculated over all 365 days of 2025 using your selected threshold and cost. A lower assumed cost is better. These are retrospective modeled outcomes; no real-world benefit is established.</p><h2>What the full benchmark says</h2><div class="table-wrap"><table><thead><tr><th>Period</th><th>Weather ridge MAE</th><th>No-weather ridge MAE</th><th>Persistence MAE</th><th>Probability model CRPS</th><th>Baseline CRPS</th><th>80% coverage</th></tr></thead><tbody id="scores"></tbody></table></div>
<p><b>January reliability limitation:</b> the nominal 80% interval covered only 61.3% of the 31 January days. Probabilities are experimental estimates; they are not demonstrated to be reliable for school decisions.</p>
<details><summary>Reliability and quantile calibration plots</summary><img src="research_results/probability_quality.png" alt="Reliability diagrams and quantile calibration for the known 2025 and January 2026 periods"><p>Bin labels show sample counts. January contains only one day at or below 55, so it provides weak evidence about false alarms.</p></details>
<details><summary>Conditional weather results</summary><img src="research_results/weather_subgroups.png" alt="Weather versus no-weather forecast error across predeclared conditions"><p>Outcome-defined spike groups are retrospective diagnostics. They cannot be used to decide in advance when the model will work.</p></details>
<p><a href="WEATHER_RESEARCH_REPORT.md">Full research report</a> · <a href="DATA_NEEDED.md">External data and stakeholder requirements</a> · <a href="SmogWindow_dashboard.html">Claude baseline dashboard (archived results)</a></p>
<footer>Sources: uploaded Lahore Zenodo/CAMS series and Open-Meteo hourly weather export. No ground-monitor, direct CAMS forecast, other-city validation or stakeholder interview has been performed. AI assistance: ChatGPT/Codex and Anthropic Claude. No external network calls are made by this dashboard.</footer>
</main><script>
/*PAYLOAD*/
const $=id=>document.getElementById(id);let revealed=false;const lock=D.metrics.selection;const rows=D.rows;
for(const r of rows){const o=document.createElement('option');o.value=r.origin_date;o.textContent=r.origin_date;$('day').appendChild(o)}
function selected(){return rows.find(r=>r.origin_date===$('day').value)}
function update(){const r=selected(),t=Number($('threshold').value),c=Number($('cost').value),p=r['p_gt_'+t];$('median').textContent=r.q50.toFixed(1);$('interval').textContent=r.q10.toFixed(1)+'–'+r.q90.toFixed(1);$('probability').textContent=(100*p).toFixed(1)+'%';$('decision').textContent='Target: '+r.target_date+'. '+(p>1/(1+c)?'Planning flag: prepare a contingency and check official information.':'No planning flag under these assumptions. This does not establish safety.')+' Decision probability threshold: '+(100/(1+c)).toFixed(1)+'%.';$('actual').textContent=revealed?'Next-day modeled reference: '+r.actual.toFixed(1)+' µg/m³. Median error: '+Math.abs(r.actual-r.q50).toFixed(1)+'.':'Future reference hidden until revealed.';$('inputs').textContent='Lagged UTC weather: mean wind '+r.lagged_wind.toFixed(1)+' km/h; total rain '+r.lagged_rain.toFixed(1)+' mm. No boundary-layer height was provided.';renderContext(r);$('points').innerHTML=[['Weather ridge',r[lock.point_weather]],['No-weather ridge',r[lock.point_no_weather]],['Persistence',r.Persistence]].map(a=>'<tr><td>'+a[0]+'</td><td>'+a[1].toFixed(1)+'</td></tr>').join('')}
$('bounds').addEventListener('change',update);
$('day').addEventListener('change',()=>{revealed=false;update()});$('threshold').addEventListener('change',update);$('cost').addEventListener('change',update);$('reveal').addEventListener('click',()=>{revealed=!revealed;update()});
$('scores').innerHTML=Object.entries(D.metrics.periods).map(([key,v])=>{const pm=v.probability[lock.probabilistic_model],pb=v.probability[lock.probabilistic_baseline];return '<tr><td>'+(key==='known_2025'?'2025 · 365 days':'January 2026 · 31 days')+'</td><td>'+v.point[lock.point_weather].mae.toFixed(2)+'</td><td>'+v.point[lock.point_no_weather].mae.toFixed(2)+'</td><td>'+v.point.Persistence.mae.toFixed(2)+'</td><td>'+pm.crps.toFixed(2)+'</td><td>'+pb.crps.toFixed(2)+'</td><td>'+(100*pm.covered).toFixed(1)+'%</td></tr>'}).join('');
$('export').addEventListener('click',()=>{const r=selected();const txt='SmogWindow post-deadline historical research\nOrigin '+r.origin_date+'; target '+r.target_date+'\nConditional median '+r.q50.toFixed(1)+'; original q10-q90 '+r.q10.toFixed(1)+' to '+r.q90.toFixed(1)+' ug/m3\nEstimated chance above '+$('threshold').value+': '+(100*r['p_gt_'+$('threshold').value]).toFixed(1)+'%\n'+$('decision').textContent+'\nCAMS estimates, not ground measurements. Lagged historical weather, not verified day-ahead weather forecasts. January interval coverage was 61.3%, not the nominal80%. No safety clearance, stakeholder validation, or direct CAMS forecast comparison.\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/plain'}));a.download='SmogWindow_research_'+r.target_date+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});

function renderContext(r){
 const adaptive=$('bounds').value==='adaptive',low=adaptive?r.cal_low:r.q10,high=adaptive?r.cal_high:r.q90;
 $('interval').textContent=low.toFixed(1)+'–'+high.toFixed(1);
 $('boundsnote').textContent=adaptive?'Rolling adjustment uses only earlier outcomes (60-day window chosen on development data). Coverage: 83.0% in 2025; 67.7% in January. This wider interval does not recalibrate the displayed probability.':'Original q10–q90 distribution. Coverage: 77.8% in 2025; 61.3% in January. Nominal coverage is 80%.';
 const ix=rows.indexOf(r),hist=rows.slice(Math.max(0,ix-29),ix+1),vals=hist.map(z=>z.Persistence),max=Math.max(high,...vals)*1.12;
 const xx=i=>55+i*(850/Math.max(1,hist.length)),yy=v=>185-v/max*155;
 const path=vals.map((v,i)=>(i?'L':'M')+xx(i)+','+yy(v)).join(' '),future=xx(hist.length);
 $('history').innerHTML='<line x1="55" y1="185" x2="920" y2="185" stroke="#64748b"/><text x="8" y="30" fill="#64748b" font-size="13">'+max.toFixed(0)+'</text><text x="20" y="185" fill="#64748b">0</text><path d="'+path+'" fill="none" stroke="#0d9488" stroke-width="3"/><line x1="'+future+'" x2="'+future+'" y1="'+yy(low)+'" y2="'+yy(high)+'" stroke="#d97706" stroke-width="4"/><circle cx="'+future+'" cy="'+yy(r.q50)+'" r="5" fill="#d97706"/><text x="55" y="210" fill="#64748b" font-size="13">'+hist[0].origin_date+'</text><text x="805" y="210" fill="#64748b" font-size="13">'+r.target_date+'</text>';
 const threshold=Number($('threshold').value),cost=Number($('cost').value),bench=rows.filter(z=>z.target_date.startsWith('2025'));let fn=0,fp=0,highdays=0,pfn=0,pfp=0;
 for(const z of bench){const event=z.actual>threshold,flag=z['p_gt_'+threshold]>1/(1+cost),pf=z.Persistence>threshold;highdays+=event;fn+=event&&!flag;fp+=!event&&flag;pfn+=event&&!pf;pfp+=!event&&pf}
 $('warningaudit').textContent='Probability flag: '+fn+' missed events, '+fp+' false alarms; assumed cost '+(cost*fn+fp)+'. Raw persistence flag cost: '+(cost*pfn+pfp)+'. Always flag: '+(bench.length-highdays)+'. Never flag: '+(cost*highdays)+'.';
}

$('day').value=rows.some(r=>r.origin_date==='2025-05-21')?'2025-05-21':rows[0].origin_date;update();
</script></body></html>'''
if __name__=='__main__':build()
